  "private": true,
  "type": "module",
  "scripts": {
    "dev": "storybook dev -c .storybook -p 6020 --no-open --disable-telemetry",
    "build": "storybook build -c .storybook -o dist --disable-telemetry",
    "preview": "vite preview --outDir dist --host 127.0.0.1 --port 6021 --strictPort"
